fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    let mut result = Vec::with_capacity(a.len());
    
    for s in a {
        if maxsplit == 0 {
            // No splitting allowed, return the original string as single element
            result.push(vec![s]);
        } else {
            // Use rsplitn with maxsplit + 1 because rsplitn's n is max number of splits
            // We want at most maxsplit splits, which means at most maxsplit + 1 parts
            let parts: Vec<String> = s.rsplitn(maxsplit as usize + 1, &sep)
                .map(|part| part.to_string())
                .collect();
            
            // rsplitn returns parts in right-to-left order, so we need to reverse
            let mut reversed_parts: Vec<String> = parts.into_iter().rev().collect();
            result.push(reversed_parts);
        }
    }
    
    result
}